404	        String message = String.valueOf(e.getMessage()).toLowerCase();
405	        if (message.contains("active_tank")) {
406	            return ApiException.conflict("发酵罐 " + req.tankCode() + " 已存在进行中批次，本次入罐不予受理");
407	        }
