45	        return ts == null ? null : ts.toLocalDateTime();
46	    }
47	
48	    /**
49	     * 按罐编号查罐 ID，不存在返回空。
50	     */
51	    public Optional<Long> findTankIdByCode(String tankCode) {
52	        return jdbc.query("SELECT id FROM fermentation_tank WHERE tank_code = ?",
53	                rs -> rs.next() ? Optional.of(rs.getLong(1)) : Optional.empty(), tankCode);
54	    }
