61	    public long insert(String batchNo, long tankId, String curveCode, int curveVersion,
62	                       LocalDateTime filledAt, String activeTankKey) {
63	        KeyHolder keyHolder = new GeneratedKeyHolder();
64	        jdbc.update(con -> {
65	            PreparedStatement ps = con.prepareStatement(
66	                    "INSERT INTO fermentation_batch (batch_no, tank_id, curve_code, curve_version, status,"
67	                            + " filled_at, maturation_extended, active_tank_key)"
68	                            + " VALUES (?, ?, ?, ?, ?, ?, 0, ?)",
69	                    Statement.RETURN_GENERATED_KEYS);
70	            ps.setString(1, batchNo);
71	            ps.setLong(2, tankId);
72	            ps.setString(3, curveCode);
73	            ps.setInt(4, curveVersion);
