        assertEquals(2, yeastUnit("Y-IDEM").get("version").asInt(), "重放不得重复增加版本");

        // 同键异参（时刻不同）：409
        MvcResult pConflict = pitch(batchId, pitchKey, "Y-IDEM", 1, T0.plusHours(2));
